style.css:
@-moz-document domain("google.com") {
/* Fondo oscuro */
body {
    background: #000 !important;
    overflow: hidden;
}

/* GIF MEME FULLSCREEN */
body::before {
    content: "";
    position: fixed;
    inset: 0;
    z-index: -1;

    background-image: url("https://media.tenor.com/q6y0Q0YtD1AAAAAC/skibidi-toilet.gif");

    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;

    filter: brightness(0.55) saturate(1.2);
}

/* Caja de búsqueda glassmorphism */
textarea,
input[name="q"] {
    background: rgba(255,255,255,0.12) !important;
    backdrop-filter: blur(12px);
    border-radius: 25px !important;
    color: white !important;
    border: 1px solid rgba(255,255,255,0.2) !important;
    padding-left: 20px !important;
}

/* Resultados */
.g, .MjjYud {
    background: rgba(0,0,0,0.45) !important;
    border-radius: 20px;
    padding: 15px !important;
    margin-bottom: 18px !important;
    backdrop-filter: blur(10px);
}

/* Texto blanco */
* {
    color: white !important;
}

/* Links neon */
a {
    color: #00ffe5 !important;
}

/* Logo Google glow */
img[alt="Google"] {
    filter:
        drop-shadow(0 0 12px #00ffe5)
        drop-shadow(0 0 25px #ff00ff);
}

/* Animación meme */
body::after {
    content: "BROOO ?";
    position: fixed;
    bottom: 20px;
    right: 30px;
    font-size: 40px;
    font-weight: bold;
    color: #fff;
    animation: memeFloat 2s infinite ease-in-out;
    text-shadow: 0 0 15px #ff00ff;
}

@keyframes memeFloat {
    0% { transform: translateY(0px) rotate(-2deg);}
    50% { transform: translateY(-10px) rotate(2deg);}
    100% { transform: translateY(0px) rotate(-2deg);}
}
}
